def fifo_faults(pages, frame_count):
    frames = []
    faults = 0
    for page in pages:
        if page in frames:
            continue
        faults += 1
        if len(frames) >= frame_count:
            frames.pop(0)
        frames.append(page)
    return faults

def belady_demo(pages):
    return fifo_faults(pages, 3), fifo_faults(pages, 4)

data = [1, 2, 3, 4, 1, 2, 5, 1, 2, 3, 4, 5]
print(fifo_faults(data, 3))
print(fifo_faults(data, 4))
print(belady_demo(data))
